def val(label,expr,key,kp,direct,method,components=None):
 p=v(label,expr,key,kp,method);p.update(assessed_8227_demand_ids=direct,component_demand_ids=components or [],given_representation='graph',response_format='numeric');return p
def washers(label,segments,key,kp,axis,method):
 expr='pi*('+ '+'.join(f'integrate(({outer})**2-({inner})**2,(x,{lo},{hi}))' for outer,inner,lo,hi in segments)+')'
 p=val(label,expr,key,kp,[VOL],method,[DEF,INT])
 p.update(rotation_axis=axis,rotation_degrees=360,source_variable='y' if axis=='y' else 'x',normalised_variable='x',units='units^3',printed_key_units='units^3',source_washer_segments=[dict(outer_radius=outer,inner_radius=inner,lower=str(lo),upper=str(hi)) for outer,inner,lo,hi in segments])
 for j,(outer,inner,lo,hi) in enumerate(segments):
  p.setdefault('additional_operations',{})[f'proper-washer-{j+1}']={'kind':'proper-definite-integral','operands':[f'({outer})**2-({inner})**2',str(lo),str(hi)]}
 return p
def add(kind,n,page,note,parts,powers):
 direct=sorted({d for p in parts for d in p.get('assessed_8227_demand_ids',[])})
 comp=sorted({d for p in parts for d in p.get('component_demand_ids',[])}-set(direct))
 r=h.add(kind,n,page,note,parts,direct,comp,powers=powers)
 r.update(representation='graph',mapping_rationale='The asked rotation axis and actual shaded region decide the radial model. Radius means NONNEGATIVE distance to the axis,not the larger signed coordinate. A y-axis rotation can require a piecewise inverse description. Separately asked area or chord equation is direct;unasked intersection calculations remain components.')
 return r
